adoption.script:
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {createRequire} from 'node:module';
const require=createRequire('/home/claude/code/EKA2L1/src/tests/wasm/package.json');
const puppeteer=require('puppeteer');
const {PNG}=require('pngjs');
const output='/home/claude/.scratch/eka-profile-plateau/registry-inline-chain/adoption';
const url='https://claude-laptop.lan:8188/';
const expectedWasm='2f57ffb2f05651659669ad86d47e41c9c3e60906fb4ebc08251629a472ad7b89';
const browser=await puppeteer.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=vulkan','--enable-features=Vulkan','--enable-gpu','--ignore-gpu-blocklist','--disable-background-timer-throttling']});
const results=[];
try {
 const system=await browser.target().createCDPSession();
 const gpu=(await system.send('SystemInfo.getInfo')).gpu;
 fs.writeFileSync(path.join(output,'gpu.json'),JSON.stringify(gpu,null,2));
 for (const [game,input,until] of [['snakes','snakes.input',23000000],['sky-force','sky-force-combat.input',42000000]]) {
  const page=await browser.newPage();await page.setViewport({width:900,height:760});
  const errors=[],messages=[];
  page.on('pageerror',e=>errors.push(String(e)));
  page.on('console',m=>{messages.push(m.text());if(m.text().includes('ABORT:'))errors.push(m.text());});
  await page.goto(url,{waitUntil:'domcontentloaded'});
  await page.waitForSelector('#game-select');await page.select('#game-select',game);
  await Promise.all([page.waitForNavigation({waitUntil:'domcontentloaded'}),page.click('#btn-play')]);
  await page.waitForFunction(()=>window._gameRunning,{timeout:180000});
  const initial=await page.evaluate(()=>({secure:isSecureContext,isolated:crossOriginIsolated,policy:window.ekaCompilerPolicy,hotpath:window.Module._eka2l1_hotpath_report(),thumbMemory:window.Module._eka2l1_thumb_memory_report(),urls:window.ekaAssetUrls}));
  if(!initial.secure||!initial.isolated||!initial.policy?.applied||initial.policy.requested.irMode!==17||initial.policy.requested.thumbMemory!==1||initial.policy.observed.thumbMemory!==1||initial.thumbMemory!==1||initial.hotpath!==2||initial.policy.observed.hotpath!==2||initial.policy.requested.hotpath!==2)throw Error('Default policy not applied: '+JSON.stringify(initial));
  if(new URL(initial.urls['/eka2l1.wasm'],url).searchParams.get('v')!==expectedWasm)throw Error('Incorrect running WASM');
  await page.focus('#canvas');
  const keys={167:'Enter',14:'ArrowLeft',15:'ArrowRight',16:'ArrowUp'};
  const events=fs.readFileSync('/home/claude/code/EKA2L1/src/tests/benchmark/'+input,'utf8').split('\n').filter(l=>l&&!l.startsWith('#')).map(l=>l.trim().split(/\s+/).map(Number));
  for (const [time,key,pressed] of events) {
   if(time>until)break;
   await page.waitForFunction(t=>window.Module._eka2l1_guest_time_us()>=t,{timeout:180000},time);
   if(pressed)await page.keyboard.down(keys[key]);else await page.keyboard.up(keys[key]);
  }
  await page.waitForFunction(t=>window.Module._eka2l1_guest_time_us()>=t,{timeout:180000},until);
  const start=await page.evaluate(()=>({guest:window.Module._eka2l1_guest_time_us(),frames:window.Module._eka2l1_presentations(),inputs:window.Module._eka2l1_input_consumed()}));
  await page.waitForFunction(s=>window.Module._eka2l1_presentations()>s.frames+2&&window.Module._eka2l1_guest_time_us()>s.guest+100000,{timeout:20000},start);
  const bytes=Buffer.from(await (await page.$('#canvas')).screenshot());fs.writeFileSync(path.join(output,game+'.png'),bytes);
  const png=PNG.sync.read(bytes),colors=new Set();for(let i=0;i<png.data.length;i+=4)colors.add((png.data[i]<<16)|(png.data[i+1]<<8)|png.data[i+2]);
  if(colors.size<4)throw Error('Trivial canvas');
  const configured=messages.find(m=>m.includes('AOT: eager_regions=')&&m.includes('ir_policy=17'));
  if(!configured)throw Error('Missing runtime confirmation of policy 17');
  if(errors.length)throw Error(errors.join('\n'));
  results.push({game,url:page.url(),...initial,start,colors:colors.size,canvas_sha256:crypto.createHash('sha256').update(png.data).digest('hex'),runtime_confirmation:configured,errors});
  fs.writeFileSync(path.join(output,'report.json'),JSON.stringify({url,expected_wasm_sha256:expectedWasm,results},null,2));fs.writeFileSync(path.join(output,game+'.log'),messages.join('\n'));
  console.log(game+': default hotpath 2, Thumb memory 1 and IR 17, correct WASM, rendered frames and input PASS');
  await page.close();
 }
} finally {await browser.close();}

